function expandStep(stepText) {
  if (!stepText || stepText.length > 120) return stepText;
  const lower = stepText.toLowerCase();
  for (const [key, expansion] of Object.entries(STEP_EXPANSIONS)) {
    if (lower.startsWith(key) || lower.includes(` ${key} `) || lower.includes(` ${key}.`)) {
      return stepText + '. ' + expansion;
    }
  }
  // Expansion générique si l'étape est trop courte
  if (stepText.length < 60) {
    return stepText + '. تأكد من إتمام هذه الخطوة بعناية قبل الانتقال للخطوة التالية.';
  }
  return stepText;
}

function getTips(recipe) {
  const cat   = recipe.cat || '';
  const area  = recipe.src_area || '';
  const diff  = recipe.df || 'e';
  const time  = parseInt(recipe.tm) || 30;
  const ings  = (recipe.ing || []).map(i => (i.n || '').toLowerCase());

  // Choisir tips par catégorie/cuisine
  const catTips = TIPS_BY_CAT[cat] || TIPS_BY_CAT[area] || TIPS_BY_CAT.default;
  const tips = [...catTips.slice(0, 3)];

  // Tips contextuels
  if (diff === 'h') tips.push('هذه الوصفة متقدمة — اقرأ الخطوات مرتين قبل البدء ولا تتسرع');
  if (time > 60)    tips.push(`هذه الوصفة تحتاج وقتاً (${recipe.tm}) — ابدأ التحضير مبكراً`);
  if (time < 20)    tips.push('وصفة سريعة! جهّز كل المكونات مقطّعة قبل إشعال النار');

  if (ings.some(i => i.includes('egg') || i.includes('بيض')))
    tips.push('أخرج البيض من الثلاجة قبل 30 دقيقة — البيض بدرجة الغرفة يعطي نتائج أفضل');
  if (ings.some(i => i.includes('flour') || i.includes('دقيق')))
    tips.push('انخل الدقيق قبل الاستخدام لتجنب التكتلات والحصول على قوام أخف');
  if (ings.some(i => i.includes('garlic') || i.includes('ثوم')))
    tips.push('الثوم الطازج المهروس أقوى نكهةً من المجفف بعشر مرات');
  if (ings.some(i => i.includes('olive') || i.includes('زيتون')))
    tips.push('استخدم زيت الزيتون البكر الممتاز للتتبيل والتقديم، وزيت عادي للقلي');

  return [...new Set(tips)].slice(0, 5);
}

// ─── MAIN ─────────────────────────────────────────────────────────────────────
const recipes = JSON.parse(fs.readFileSync(DATA_PATH, 'utf8'));

// Identifier les recettes à enrichir
const toEnrich = recipes
  .map((r, i) => ({ r, i }))
  .filter(({ r }) => !Array.isArray(r.steps) || r.steps.length === 0 || r.steps.every(s => !s.tp))
  .slice(0, BATCH);

console.log(`📝 Enrichissement local — ${toEnrich.length}/${recipes.length} recettes (batch ${BATCH})`);

let enriched = 0;
for (const { r, i } of toEnrich) {
  // Expand steps
  if (Array.isArray(r.steps) && r.steps.length > 0) {
    recipes[i].steps = r.steps.map(s => ({
      ...s,
      tp: expandStep(typeof s === 'string' ? s : s.t || s.tp || ''),
    }));
  } else {
    recipes[i].steps = [
      { t: 'التحضير', tp: 'جهّز جميع المكونات وقطّعها حسب المقادير المطلوبة قبل البدء في الطهي.' },
      { t: 'الطهي', tp: 'اتبع خطوات الوصفة بعناية مع مراعاة درجة الحرارة والتوقيت.' },
      { t: 'التقديم', tp: 'قدّم الطبق ساخناً مزيّناً حسب ذوقك. صحتين وعافية!' },
    ];
  }

  // Generate tips
  if (!recipes[i].tips || recipes[i].tips.length === 0) {
    recipes[i].tips = getTips(r);
  }

  // Enrich short description
  if (!r.de || r.de.length < 80) {
    const cat  = r.cat || r.src_area || 'عالمي';
    const name = r.ti || '';
    recipes[i].de = `اكتشف وصفة ${name} التقليدية من المطبخ ${cat} بمكوناتها الأصيلة وطريقة تحضيرها المفصّلة خطوة بخطوة. وجبة شهية مثالية للعائلة تجمع الأصالة مع سهولة التحضير.`;
  }

  enriched++;
}

fs.writeFileSync(DATA_PATH, JSON.stringify(recipes, null, 2));

const remaining = recipes.filter(r => !r.steps || r.steps.every(s => !s.tp)).length;
console.log(`✅ ${enriched} recettes enrichies | restantes: ${remaining}`);
